using GestionTubos.Application.Interfaces;using GestionTubos.Domain.Entities;using GestionTubos.Domain.Enums;using GestionTubos.Infrastructure.Data;using GestionTubos.Shared.Repartos;using Microsoft.EntityFrameworkCore;
namespace GestionTubos.Infrastructure.Services;
public sealed class RepartoService(GestionTubosDbContext db):IRepartoService
{
 public async Task<IReadOnlyList<RepartoDto>>ObtenerAsync(CancellationToken ct)=>await db.Repartos.AsNoTracking().OrderByDescending(x=>x.Fecha).ThenByDescending(x=>x.Id).Select(x=>new RepartoDto(x.Id,x.Numero,x.Fecha,x.Responsable,x.Estado,x.FechaCreacionUtc,x.FechaSalidaUtc,x.UsuarioCreador,x.Observaciones,x.Detalles.Select(d=>new RepartoPedidoDto(d.PedidoId,d.Pedido.Numero,d.Pedido.Remito!.Numero,d.Pedido.Cliente.RazonSocial??((d.Pedido.Cliente.Apellido??"")+" "+(d.Pedido.Cliente.Nombre??"")).Trim(),d.Pedido.Detalles.Count,d.Estado)).ToList())).ToListAsync(ct);
 public async Task<RepartoDto>CrearAsync(RepartoCrearDto dto,string usuario,CancellationToken ct){var ids=dto.PedidoIds.Distinct().ToList();if(ids.Count==0)throw new InvalidOperationException("Seleccioná al menos un pedido.");var pedidos=await db.Pedidos.Include(x=>x.Remito).Include(x=>x.RepartoDetalle).Where(x=>ids.Contains(x.Id)).ToListAsync(ct);if(pedidos.Count!=ids.Count||pedidos.Any(x=>x.Estado!="Preparado"||x.Remito==null||x.RepartoDetalle!=null||x.ModalidadEntrega!="Domicilio"))throw new InvalidOperationException("Sólo los pedidos a domicilio preparados pueden agregarse al reparto.");var siguiente=(await db.Repartos.MaxAsync(x=>(long?)x.Id,ct)??0)+1;var reparto=new Reparto{Numero=$"REP-{siguiente:000000}",Fecha=dto.Fecha,Responsable=dto.Responsable.Trim(),UsuarioCreador=usuario,Observaciones=Limpiar(dto.Observaciones)};foreach(var p in pedidos)reparto.Detalles.Add(new RepartoDetalle{Pedido=p});db.Add(reparto);await db.SaveChangesAsync(ct);return(await ObtenerAsync(ct)).Single(x=>x.Id==reparto.Id);}
 public async Task<RepartoDto>IniciarAsync(long id,string usuario,CancellationToken ct){var reparto=await db.Repartos.Include(x=>x.Detalles).ThenInclude(x=>x.Pedido).ThenInclude(x=>x.Detalles).ThenInclude(x=>x.Tubo).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new InvalidOperationException("El reparto no existe.");if(reparto.Estado!="Preparado")throw new InvalidOperationException("El reparto ya fue iniciado.");foreach(var d in reparto.Detalles){if(d.Pedido.Estado!="Preparado"||d.Pedido.Detalles.Any(x=>x.Tubo.EstadoDisponibilidad!=EstadoDisponibilidad.Reservado))throw new InvalidOperationException("Un pedido ya no está preparado.");foreach(var pd in d.Pedido.Detalles){var t=pd.Tubo;var anterior=Estado(t);t.EstadoDisponibilidad=EstadoDisponibilidad.EnReparto;db.MovimientosCilindro.Add(new(){TuboId=t.Id,Tipo="Salida a reparto",UbicacionOrigenId=t.UbicacionId,ClienteId=d.Pedido.ClienteId,EstadoAnterior=anterior,EstadoPosterior=Estado(t),UsuarioResponsable=usuario,Observaciones=$"{reparto.Numero} / {d.Pedido.Numero}"});}d.Pedido.Estado="En reparto";d.Estado="En reparto";}reparto.Estado="En reparto";reparto.FechaSalidaUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return(await ObtenerAsync(ct)).Single(x=>x.Id==id);}
 public async Task<RepartoDto>AnularAsync(long id,RepartoAnularDto dto,string usuario,CancellationToken ct){var reparto=await db.Repartos.Include(x=>x.Detalles).ThenInclude(x=>x.Pedido).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new InvalidOperationException("El reparto no existe.");if(reparto.Estado!="Preparado")throw new InvalidOperationException("Sólo se puede anular un reparto que todavía no salió de planta.");var pedidos=string.Join(", ",reparto.Detalles.Select(x=>x.Pedido.Numero));reparto.Observaciones=AgregarNovedad(reparto.Observaciones,$"ANULADO por {usuario}. Motivo: {dto.Motivo.Trim()}. Pedidos liberados: {pedidos}");reparto.Estado="Anulado";db.RepartoDetalles.RemoveRange(reparto.Detalles);await db.SaveChangesAsync(ct);return(await ObtenerAsync(ct)).Single(x=>x.Id==id);}
 public async Task<RepartoDto>NoEntregadoAsync(long id,long pedidoId,RepartoNoEntregadoDto dto,string usuario,CancellationToken ct){if(dto.Accion is not ("Reprogramar" or "CancelarPedido"))throw new InvalidOperationException("La acción seleccionada no es válida.");if(!await db.Ubicaciones.AnyAsync(x=>x.Id==dto.UbicacionRetornoId,ct))throw new InvalidOperationException("La ubicación de retorno no existe.");var reparto=await db.Repartos.Include(x=>x.Detalles).ThenInclude(x=>x.Pedido).ThenInclude(x=>x.Remito).Include(x=>x.Detalles).ThenInclude(x=>x.Pedido).ThenInclude(x=>x.Detalles).ThenInclude(x=>x.Tubo).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new InvalidOperationException("El reparto no existe.");if(reparto.Estado!="En reparto")throw new InvalidOperationException("El reparto no se encuentra en curso.");var detalle=reparto.Detalles.FirstOrDefault(x=>x.PedidoId==pedidoId)??throw new InvalidOperationException("El pedido no pertenece al reparto.");if(detalle.Estado!="En reparto")throw new InvalidOperationException("El pedido ya fue procesado.");var cancelar=dto.Accion=="CancelarPedido";foreach(var pd in detalle.Pedido.Detalles){var t=pd.Tubo;var anterior=Estado(t);var origen=t.UbicacionId;t.UbicacionId=dto.UbicacionRetornoId;t.EstadoDisponibilidad=cancelar?EstadoDisponibilidad.Disponible:EstadoDisponibilidad.Reservado;db.MovimientosCilindro.Add(new(){TuboId=t.Id,Tipo="Retorno sin entrega",UbicacionOrigenId=origen,UbicacionDestinoId=t.UbicacionId,ClienteId=detalle.Pedido.ClienteId,EstadoAnterior=anterior,EstadoPosterior=Estado(t),UsuarioResponsable=usuario,Observaciones=$"{reparto.Numero} / {detalle.Pedido.Numero}. {dto.Motivo.Trim()}. {(cancelar?"Pedido cancelado":"Pendiente de reprogramación")}"});}detalle.Pedido.Estado=cancelar?"Cancelado":"Preparado";if(cancelar&&detalle.Pedido.Remito is not null)detalle.Pedido.Remito.Estado="Anulado";reparto.Observaciones=AgregarNovedad(reparto.Observaciones,$"NO ENTREGADO {detalle.Pedido.Numero}: {dto.Motivo.Trim()}. Acción: {(cancelar?"pedido cancelado":"reprogramar")}. Registrado por {usuario}");db.RepartoDetalles.Remove(detalle);if(!reparto.Detalles.Where(x=>x.Id!=detalle.Id).Any(x=>x.Estado=="En reparto"))reparto.Estado="Completado con novedades";await db.SaveChangesAsync(ct);return(await ObtenerAsync(ct)).Single(x=>x.Id==id);}
 private static string AgregarNovedad(string?actual,string novedad){var linea=$"[{GestionTubos.Shared.HoraArgentina.Ahora:dd/MM/yyyy HH:mm}] {novedad}";var resultado=string.IsNullOrWhiteSpace(actual)?linea:$"{actual}\n{linea}";return resultado.Length<=1000?resultado:resultado[^1000..];}private static string Estado(Tubo x)=>$"Físico={(int)x.EstadoFisico};Contenido={(int)x.EstadoContenido};Disponibilidad={(int)x.EstadoDisponibilidad};Ubicación={x.UbicacionId}";private static string?Limpiar(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();
}
